/**
 * `users.info` records, cached per token. Shared by everything that needs a
 * user's record — externality and display name — and the in-flight request
 * is what is cached, so two of them in one turn still cost one call.
 */
import { callSlackApi } from "./api.js";
import { isRecord } from "../../internal/is-record.js";
function text(value) {
    return typeof value === "string" && value !== "" ? value : undefined;
}
function record(value) {
    return isRecord(value) ? value : undefined;
}
export function slackUserName(user) {
    const profile = record(user.profile);
    return (text(profile?.display_name) ??
        text(profile?.real_name) ??
        text(user.real_name) ??
        text(user.name));
}
const users = new Map();
export function resetSlackUserInfoCache() {
    users.clear();
}
async function fetch(botToken, userId) {
    const result = await callSlackApi({
        botToken,
        operation: "users.info",
        body: { user: userId },
    });
    const user = result.user;
    return result.ok === true && isRecord(user) ? user : undefined;
}
/** Undefined when the lookup fails; failures are not cached. */
export async function fetchSlackUserInfo(args) {
    const perToken = users.get(args.botToken) ?? new Map();
    users.set(args.botToken, perToken);
    const cached = perToken.get(args.userId);
    if (cached !== undefined) {
        return cached;
    }
    const pending = fetch(args.botToken, args.userId);
    perToken.set(args.userId, pending);
    try {
        const record = await pending;
        if (record === undefined) {
            perToken.delete(args.userId);
        }
        return record;
    }
    catch (error) {
        perToken.delete(args.userId);
        throw error;
    }
}
